import{_ as p,a0 as l,w as o,s as h,ao as d,I as t,x as a,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"使用 Linux 實用程序 gPhoto2 備份手機存儲 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Linux 實用程序 gPhoto2 備份手機存儲 | LCTT (202007) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Linux 實用程序 gPhoto2 備份手機存儲 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Linux 實用程序 gPhoto2 備份手機存儲 | LCTT (202007) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202007/20200701 Back up your phone-s storage with this Linux utility","title":"使用 Linux 實用程序 gPhoto2 備份手機存儲","tag":"202007","desc":""},"relativePath":"202007/20200701 Back up your phone-s storage with this Linux utility.md","filePath":"[post].md"}'),r={name:"202007/20200701 Back up your phone-s storage with this Linux utility.md"};function g(c,s,u,k,b,f){const e=l("Link");return o(),h("div",null,[s[15]||(s[15]=d(`<h1 id="使用-linux-實用程序-gphoto2-備份手機存儲" tabindex="-1">使用 Linux 實用程序 gPhoto2 備份手機存儲 <a class="header-anchor" href="#使用-linux-實用程序-gphoto2-備份手機存儲" aria-label="Permalink to “使用 Linux 實用程序 gPhoto2 備份手機存儲”">​</a></h1><blockquote><p>盡情地拍照吧，gphoto2 能夠方便、快速地將照片從你的設備傳輸到 Linux 計算機上。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202007/14/170729pzljppapojy44ro4.jpg" alt=""></p><p>移動設備的最大缺點之一就是其將數據從設備傳輸到計算機很困難。移動設備在這一缺點上有着悠久的歷史。早期的移動設備，如 Pilot 和掌上電腦 PDA 設備，需要使用特殊的同步軟件來傳輸數據（你必須小心翼翼地做這件事，因為你的設備可能會因為電池耗盡而導致數據永久丟失）；舊版 iPod 只提供特定平台的界面。現代移動設備默認將你的數據發送到在線帳户，以便你可以在計算機上再次下載。</p><p>好消息——如果你正在運行 Linux，你可以使用 <code>gphoto2</code> 命令與移動設備進行連接。<code>gphoto2</code> 最初是作為一種與數碼相機通信的方式而開發的，那時的數碼相機只有傳統的相機功能，現在的 <code>gphoto2</code> 可以和許多不同種類的移動設備通訊。別讓這個名字騙了你，它可以處理所有類型的文件，而不僅僅是照片。更棒的是，它可以編寫腳本、很靈活、並且比大多數 GUI 界面功能強大得多。</p><p>如果你曾經為在計算機和移動設備之間同步數據而苦惱，請了解一下 <code>gphoto2</code>。</p><h3 id="安裝-gphoto2" tabindex="-1">安裝 gPhoto2 <a class="header-anchor" href="#安裝-gphoto2" aria-label="Permalink to “安裝 gPhoto2”">​</a></h3><p>很可能你的 Linux 系統已經安裝了 libgphoto2，因為它是與移動設備連接的一個關鍵庫，但你可能還需要安裝命令 <code>gphoto2</code>，該命令可能在你的存儲庫中。</p><p>在 Fedora 或 RHEL 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install gphoto2</span></span></code></pre></div><p>在 Debian 或 Ubuntu 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install gphoto2</span></span></code></pre></div><h3 id="驗證兼容性" tabindex="-1">驗證兼容性 <a class="header-anchor" href="#驗證兼容性" aria-label="Permalink to “驗證兼容性”">​</a></h3><p>若要確認你的移動設備是否受支持，請使用 <code>--list-cameras</code>，通過管道傳輸到 <code>less</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gPhoto2 --list-cameras | less</span></span></code></pre></div><p>或者你可以通過管道把它傳送到 <code>grep</code> 來搜索一個詞。例如，如果你有三星 Galaxy，則使用 <code>grep</code>，並通過選項 <code>-i</code> 關閉區分大小寫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --list-cameras | grep -i galaxy</span></span>
<span class="line"><span>  &quot;Samsung Galaxy models (MTP)&quot;</span></span>
<span class="line"><span>  &quot;Samsung Galaxy models (MTP+ADB)&quot;</span></span>
<span class="line"><span>  &quot;Samsung Galaxy models Kies mode&quot;</span></span></code></pre></div><p>這證實了三星 Galaxy 設備支持通過 MTP 連接和通過 ADB 連接 MTP。</p><p>如果你沒有在列表中找到自己的移動設備，你仍然可以嘗試使用 <code>gphoto2</code>，可能你的設備在列表中使用了不同的稱呼。</p><h3 id="查找移動設備" tabindex="-1">查找移動設備 <a class="header-anchor" href="#查找移動設備" aria-label="Permalink to “查找移動設備”">​</a></h3><p>要使用 gPhoto2，首先必須將移動設備插入計算機，設置為 MTP 模式，並且授予計算機與它交互的權限。這通常需要在你的移動設備上操作，往往是在屏幕上按下一個按鈕，以允許其文件系統被剛剛連接的計算機訪問。</p><p><img src="https://opensource.com/sites/default/files/uploads/gphoto2-mtp-allow.jpg" alt="Screenshot of allow access message" title="Screenshot of allow access message"></p><p>如果你不授權電腦訪問移動設備，那麼 gPhoto2 可以檢測到你的移動設備，但它不能與之交互。</p><p>要確保計算機檢測到你連接的移動設備，請使用 <code>--auto-detect</code> 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --auto-detect</span></span>
<span class="line"><span>Model                       Port</span></span>
<span class="line"><span>---------------------------------------</span></span>
<span class="line"><span>Samsung Galaxy models (MTP) usb:002,010</span></span></code></pre></div><p>如果你的移動設備沒有被檢測到，請先檢查數據線，然後檢查你的設備是否配置為通過 MTP、ADB 或其它 gPhoto2 支持的協議連接，如 <code>--list-cameras</code> 所示。</p><h3 id="查詢你的設備支持的特性" tabindex="-1">查詢你的設備支持的特性 <a class="header-anchor" href="#查詢你的設備支持的特性" aria-label="Permalink to “查詢你的設備支持的特性”">​</a></h3><p>對於現代設備，通常有過多的潛在功能，但並非所有移動設備都支持這些功能。你可以用 <code>--abilities</code> 選項來確定自己的移動設備支持哪些功能。我覺得結果看起來直觀。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --abilities</span></span>
<span class="line"><span>Abilities for camera            : Samsung Galaxy models (MTP)</span></span>
<span class="line"><span>Serial port support             : no</span></span>
<span class="line"><span>USB support                     : yes</span></span>
<span class="line"><span>Capture choices                 : Capture not supported by driver</span></span>
<span class="line"><span>Configuration support           : no</span></span>
<span class="line"><span>Delete selected files on camera : yes</span></span>
<span class="line"><span>Delete all files on camera      : no</span></span>
<span class="line"><span>File preview (thumbnail) support: no</span></span>
<span class="line"><span>File upload support             : yes</span></span></code></pre></div><p>如果只連接一個設備，那麼不需要指定查詢的設備。但是，如果連接了多個 gPhoto2 可以與之交互的設備，則可以通過端口、相機型號或 usbid 指定設備。</p><h3 id="與你的移動設備交互" tabindex="-1">與你的移動設備交互 <a class="header-anchor" href="#與你的移動設備交互" aria-label="Permalink to “與你的移動設備交互”">​</a></h3><p>如果你的設備支持拍攝功能，則可以從計算機調用你的攝像頭來獲取媒體。例如，要拍攝照片：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --capture-image</span></span></code></pre></div><p>要拍攝照片並立即將其傳輸到連接的計算機：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --capture-image-and-download</span></span></code></pre></div><p>你也可以錄製視頻和聲音。如果連接了多個拍攝設備，可以按端口、相機型號或 usbid 指定要使用的設備：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --camera &quot;Samsung Galaxy models (MTP)&quot; \\</span></span>
<span class="line"><span>--capture-image-and-download</span></span></code></pre></div><h3 id="文件和文件夾" tabindex="-1">文件和文件夾 <a class="header-anchor" href="#文件和文件夾" aria-label="Permalink to “文件和文件夾”">​</a></h3><p>要想更加智能地管理移動設備上的文件，你需要了解 gPhoto2 連接的文件系統的結構。</p><p>你可以使用 <code>--get-folders</code> 選項查看可用文件夾：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --list-folders</span></span>
<span class="line"><span>There are 2 folders in folder &#39;/&#39;.                                            </span></span>
<span class="line"><span> - store_00010001</span></span>
<span class="line"><span> - store_00020002</span></span>
<span class="line"><span>There are 0 folders in folder &#39;/store_00010001&#39;.</span></span>
<span class="line"><span>There are 0 folders in folder &#39;/store_00020002&#39;.</span></span></code></pre></div><p>每個文件夾代表設備上的一個存儲單元。在本例中，<code>store_00010001</code> 是內部存儲器，<code>store_00020002</code> 是 SD 卡，這可能與你的設備的結構不同。</p><h3 id="獲取文件" tabindex="-1">獲取文件 <a class="header-anchor" href="#獲取文件" aria-label="Permalink to “獲取文件”">​</a></h3><p>現在你知道了設備的文件夾佈局，就可以從設備獲取照片了。你可以使用許多不同的選項，具體取決於你想從設備中獲取什麼。</p><p>如果你知道絕對路徑，則可以獲取指定的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --get-file IMG_0001.jpg --folder /store_00010001/myphotos</span></span></code></pre></div><p>你可以同時獲得所有的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --get-all-files --folder /store_00010001/myfiles</span></span></code></pre></div><p>你可以只獲取音頻文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gphoto2 --get-all-audio-data --folder /store_00010001/mysounds</span></span></code></pre></div><p>gPhoto2 還有其他的選擇，其中大多數取決於你連接的設備和使用協議是否支持。</p><h3 id="上傳文件" tabindex="-1">上傳文件 <a class="header-anchor" href="#上傳文件" aria-label="Permalink to “上傳文件”">​</a></h3><p>現在你知道了潛在的目標文件夾，就可以將文件從計算機上傳到你的設備。例如，假設有一個名為 <code>example.epub</code> 的文件在當前目錄中，你可以使用 <code>--upload-file</code> 選項和 <code>--folder</code> 選項將文件發送到設備並指定要上傳到的目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --upload file example.epub \\</span></span>
<span class="line"><span>--folder store_00010001</span></span></code></pre></div><p>如果你希望將多個文件上傳到同一個位置，你可以在設備上創建一個目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --mkdir books \\</span></span>
<span class="line"><span>--folder store_00010001</span></span>
<span class="line"><span>$ gphoto2 --upload-file *.epub \\</span></span>
<span class="line"><span>--folder store_00010001/books</span></span></code></pre></div><h3 id="列出文件" tabindex="-1">列出文件 <a class="header-anchor" href="#列出文件" aria-label="Permalink to “列出文件”">​</a></h3><p>若要查看設備上的文件，請使用 <code>--list-files</code> 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --list-files --folder /store_00010001</span></span>
<span class="line"><span>There is 1 file in folder &#39;/store_00010001&#39;</span></span>
<span class="line"><span>#1     example.epub 17713 KB application/x-unknown</span></span>
<span class="line"><span>$ gphoto2 --list-files --folder /store_00010001/books</span></span>
<span class="line"><span>There is 1 file in folder &#39;/store_00010001&#39;</span></span>
<span class="line"><span>#1    example0.epub 17713 KB application/x-unknown</span></span>
<span class="line"><span>#2    example1.epub 12264 KB application/x-unknown</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><h3 id="探索你的使用方式" tabindex="-1">探索你的使用方式 <a class="header-anchor" href="#探索你的使用方式" aria-label="Permalink to “探索你的使用方式”">​</a></h3><p>gPhoto2 的大部分功能取決於你的設備，因此不同用户的體驗可能不盡相同。在 <code>gphoto2 --help</code> 中列出了許多操作供你探索。使用gPhoto2，再也不用費勁把文件從你的設備傳輸到電腦上了！</p><p>這些開源圖片庫能夠幫助你組織文件，並讓的圖片看起來很棒。</p><hr>`,63)),t("p",null,[s[1]||(s[1]=a("via: ",-1)),i(e,{href:"https://opensource.com/article/20/7/gphoto2-linux"},{default:n(()=>[...s[0]||(s[0]=[a("https://opensource.com/article/20/7/gphoto2-linux",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=a("作者：",-1)),i(e,{href:"https://opensource.com/users/seth"},{default:n(()=>[...s[2]||(s[2]=[a("Seth Kenlon",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),i(e,{href:"https://github.com/summer2233"},{default:n(()=>[...s[4]||(s[4]=[a("summer2233",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:n(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const C=p(r,[["render",g]]);export{y as __pageData,C as default};
